package maven

import (
	"context"
	"errors"
	"io"
	"net/http"
	"strings"

	"commandcenter/internal/repo"
)

// Ingest stores one file of a hosted Maven repository at path, the way a PUT
// stores an artifact (version policy, path rules), and reports whether it was
// stored or skipped. Checksum sidecars (.sha1, .md5, .sha256, .sha512) and
// maven-metadata.xml* are generated by Command Center and are Skipped without
// reading r. A file already stored with the same content is Skipped, whatever
// the write policy (a re-run of an import); a different content at the same
// path is a conflict (repo.IsIngestConflict) and nothing is overwritten. It
// makes no privilege checks and ignores a deny write policy: the caller is the
// admin import. The GA metadata is not touched: call RebuildGA after the files
// of a GA.
func (h *Handler) Ingest(ctx context.Context, rp *repo.Repository, path string, r io.Reader, actor string) (repo.IngestResult, error) {
	p, err := ParsePath(path)
	if err != nil {
		return "", err
	}
	if err := validateWritePath(p.Path); err != nil {
		return "", err
	}
	if p.Hash != "" || p.Metadata || strings.Contains(p.Main, "maven-metadata.xml") {
		return repo.Skipped, nil
	}
	if err := checkVersionPolicy(rp.VersionPolicy, p); err != nil {
		return "", err
	}
	if p.Coords == nil {
		return "", repo.Errorf(http.StatusBadRequest, "%q is not a valid maven artifact path", p.Main)
	}
	sums, err := h.Store.WriteBlob(rp.Name, r, nil)
	if err != nil {
		return "", err
	}

	unlock := h.locks.Lock("asset\x00" + rp.Name + "\x00" + p.Main)
	defer unlock()
	old, err := h.Store.Get(ctx, rp.Name, p.Main)
	switch {
	case err == nil && old.BlobSHA256 == sums.SHA256:
		return repo.Skipped, nil
	case err == nil:
		return "", repo.IngestConflict("%s already exists with different content", p.Main)
	case !errors.Is(err, repo.ErrNotFound):
		return "", err
	}
	if err := h.Store.Current(rp); err != nil {
		return "", err
	}
	if err := h.Store.DB.PutAsset(ctx, h.Store.NewAsset(rp.Name, p.Main, ContentType(p.Main), sums)); err != nil {
		return "", err
	}
	if !strings.HasSuffix(p.Main, ".asc") { // signatures are sidecars, not components
		h.Store.EmitAs("upload", actor, rp.Name, p.Main, "")
	}
	return repo.Ingested, nil
}

// RebuildGA regenerates maven-metadata.xml of the GA in directory gaDir
// ("com/acme/lib": the groupId with slashes, then the artifactId) from its
// stored artifacts, and the version-level documents of its SNAPSHOT versions.
// The importer calls it after a GA's files are in.
func (h *Handler) RebuildGA(ctx context.Context, rp *repo.Repository, gaDir string) error {
	gaDir = strings.Trim(gaDir, "/")
	i := strings.LastIndexByte(gaDir, '/')
	if i <= 0 || i == len(gaDir)-1 {
		return repo.Errorf(http.StatusBadRequest, "%q is not a GA directory", gaDir)
	}
	group, artifact := strings.ReplaceAll(gaDir[:i], "/", "."), gaDir[i+1:]
	if err := h.rebuildGA(ctx, rp, group, artifact, true); err != nil {
		return err
	}
	assets, err := h.Store.DB.ListAssets(ctx, rp.Name, gaDir+"/")
	if err != nil {
		return err
	}
	snaps := map[string]bool{}
	for _, a := range assets {
		pp, err := ParsePath(a.Path)
		if err == nil && pp.Coords != nil && pp.Coords.Snapshot && pp.Coords.GroupID == group && pp.Coords.ArtifactID == artifact {
			snaps[dir(pp.Main)] = true
		}
	}
	for d := range snaps {
		if err := h.rebuildSnapshotVersion(ctx, rp, d); err != nil {
			return err
		}
	}
	return nil
}
